#!/usr/bin/env node
/**
 * `npm run roleplay-voices:generate` — derives the frontend's roleplay voice
 * lookup from oracle's own pregenerated-speech manifest.
 *
 * WHY A GENERATED FILE RATHER THAN A NEW ENDPOINT. `oracle/speech.
 * pregenerated.json` already holds every roleplay clip's URL, keyed by a
 * content hash the frontend has no way to independently derive (it would
 * need oracle's own voice-fingerprint resolution to do it). Core is the
 * only service the frontend calls (/AGENTS.md §1.5), and oracle's manifest
 * is not secret — "tracked config... URLs to world-readable audio," per its
 * own header — so a new authenticated round trip through Core would add a
 * live dependency to serve a value that never changes at runtime. A
 * committed, regenerated-on-demand file is the same posture `repo_map.md`
 * already has for a different cross-cutting derivation, and it is the
 * cheaper, more honest answer to "how does the client find the URL that
 * demonstrably already exists."
 *
 * WHAT IT WRITES. `frontend/src/rebuild/mentor/session/roleplayVoices.generated.json`:
 * `{ [sceneId]: { [beatIndex]: { [characterId]: { [locale]: url } } } }` —
 * shaped for the exact lookup `useRoleplayDirector.ts` needs (the resolved
 * speaker's id, the beat's own index, the session's locale), never the
 * content hash or any other detail of how oracle got there.
 *
 * WHEN TO RE-RUN. After `npm run speech:pregenerate -- --confirm` in
 * `oracle/` adds or changes any `roleplay.*` entry — this script does not
 * itself talk to Depot or Inworld, so it costs nothing and makes no network
 * call; it only reshapes a file that already exists.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const MANIFEST_PATH = path.join(ROOT, 'oracle/speech.pregenerated.json');
const OUT_PATH = path.join(ROOT, 'frontend/src/rebuild/mentor/session/roleplayVoices.generated.json');

function main() {
  const manifest = JSON.parse(readFileSync(MANIFEST_PATH, 'utf8'));
  const lines = manifest.lines ?? {};

  /** @type {Record<string, Record<string, Record<string, Record<string, string>>>>} */
  const out = {};
  let count = 0;

  for (const entry of Object.values(lines)) {
    const m = /^roleplay\.([a-z_]+)\.(\d+)$/.exec(entry.key ?? '');
    if (!m) continue;
    const [, sceneId, beatIndex] = m;
    out[sceneId] ??= {};
    out[sceneId][beatIndex] ??= {};
    out[sceneId][beatIndex][entry.character] ??= {};
    out[sceneId][beatIndex][entry.character][entry.locale] = entry.url;
    count += 1;
  }

  const payload = {
    _comment:
      'GENERATED by `npm run roleplay-voices:generate` (agent/tools/generate-roleplay-voices.mjs) from ' +
      'oracle/speech.pregenerated.json. Do not hand-edit — re-run the generator instead.',
    generated: new Date().toISOString().slice(0, 10),
    voices: out,
  };

  writeFileSync(OUT_PATH, `${JSON.stringify(payload, null, 2)}\n`, 'utf8');
  console.log(`Wrote ${count} roleplay voice URL(s) to frontend/src/rebuild/mentor/session/roleplayVoices.generated.json`);
}

main();
